export async function getDocumentAsync(options:any={}){return new Promise<any>(resolve=>{const input=document.createElement('input');input.type='file';input.accept=Array.isArray(options.type)?options.type.join(','):(options.type||'*/*');input.multiple=!!options.multiple;input.onchange=()=>resolve({canceled:!input.files?.length,assets:Array.from(input.files||[]).map((file:any)=>({file,name:file.name,size:file.size,mimeType:file.type,uri:URL.createObjectURL(file)}))});input.click()})}
